// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // Precondition: the contract is not yet initialized
        // We set MinSum via SetMinSum, ensuring initialization does not happen
        // Then we call Collect, and verify MinSum stays as set
        uint256 originalMinSum = _val % 1 ether;
        c.SetMinSum(originalMinSum);

        // Now call Collect (without initializing) - it should revert because balances[msg.sender] < MinSum
        // But we only care about MinSum after the call
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, 0));

        // The property: MinSum remains unchanged from what we set
        assertTrue(c.MinSum() == originalMinSum, "MinSum changed");
    }
}

